/* Common Japanese expressions with original anime-style practice scenes. */
(function(root){
 'use strict';
 function create({getState,save,render,speak,hasJapaneseVoice,toast,esc,I}){
  const D=KanaDialogueData,L=KanaLearning;
  const ui={group:'all',filter:'all',selected:'ohayou',showReading:true,mode:'meaning'};
  let quiz=null;
  const find=id=>D.lines.find(l=>l.id===id);
  function progress(){const s=getState();if(!s.dialogue)s.dialogue={learned:[],records:{}};return s.dialogue;}
  function pool(){const p=progress();return D.lines.filter(l=>(ui.group==='all'||l.group===ui.group)&&(ui.filter==='all'||ui.filter==='learned'&&p.learned.includes(l.id)||ui.filter==='review'&&p.records[l.id]?.review));}
  function stats(){const p=progress(),r=Object.values(p.records);return {learned:p.learned.length,review:r.filter(x=>x.review).length,attempts:r.reduce((n,x)=>n+x.attempts,0),correct:r.reduce((n,x)=>n+x.correct,0)};}
  function tokenInfo(line,token,index){
   if(token==='っ')return {roman:'停一拍',detail:'促音っ不单独读作 tsu；在后面的辅音前短暂停顿。'};
   const sound=D.spokenToken(line,index),entry=KanaData.entries.find(e=>e.hira===sound||e.kata===sound);
   return {roman:entry?.romaji||sound,detail:token!==sound?`${token} 在这里读 ${entry?.romaji||sound}。${line.note}`:`${token} → ${entry?.romaji||sound}。${token===line.focus?line.note:'再听整句，感受它在词语中的声音。'}`};
  }
  function intro(){return `<div class="view-intro dialogue-intro"><div><div class="eyebrow">ANIME DIALOGUE CLUB · 台词教室</div><h1>听懂一句，走进一个小故事。</h1><p>用常见日语表达，练习假名、读音和说话的场合。</p></div><div class="dialogue-seal" lang="ja" aria-hidden="true">言<span>ことばの部室</span></div></div>`;}
  function controls(){return `<div class="dialogue-filters"><div class="pills" aria-label="台词场景">${[['all',{name:'全部台词',icon:'✧'}],...Object.entries(D.groups)].map(([id,g])=>`<button class="pill ${ui.group===id?'active':''}" aria-pressed="${ui.group===id}" data-action="dialogue-group" data-group="${id}">${g.icon} ${g.name}</button>`).join('')}</div><label class="dialogue-filter-label">显示<select id="dialogue-filter" aria-label="台词学习状态"><option value="all" ${ui.filter==='all'?'selected':''}>全部</option><option value="learned" ${ui.filter==='learned'?'selected':''}>已熟悉</option><option value="review" ${ui.filter==='review'?'selected':''}>待复习</option></select></label></div>`;}
  function lineCard(line){const tokens=D.tokenize(line.kana),familiar=progress().learned.includes(line.id),group=D.groups[line.group];return `<section class="dialogue-detail panel"><div class="dialogue-card-top"><span class="source-label">${group.icon} ${group.name}</span><span>SCENE ${String(D.lines.indexOf(line)+1).padStart(2,'0')}</span></div><div class="scene-caption">${I('spark')}<span>${line.scene}</span></div><div class="dialogue-quote" lang="ja">${line.text}</div><div class="dialogue-translation">${line.meaning}</div><div class="dialogue-reading ${ui.showReading?'':'concealed'}" ${ui.showReading?'':'aria-hidden="true"'}><span lang="ja">${line.kana}</span><small>${line.romaji}</small></div><div class="dialogue-listen"><button class="button" data-action="dialogue-speak" data-id="${line.id}">${I('sound')}听整句</button><button class="button secondary" data-action="dialogue-mark" data-id="${line.id}" aria-pressed="${familiar}">${I(familiar?'check':'leaf')}${familiar?'已标熟悉':'这句我记住了'}</button><label class="switch-label"><input id="dialogue-reading" type="checkbox" ${ui.showReading?'checked':''}>显示读音</label></div><div class="dialogue-divider"></div><div class="dialogue-section-title"><h2>拆开看，每一拍都认识。</h2><span>点假名，听读音 / 看提示</span></div><div class="mora-strip" aria-label="台词假名拆解">${tokens.map((t,i)=>{const info=tokenInfo(line,t,i);return `<button class="mora ${t===line.focus?'focus-mora':''}" data-action="dialogue-token" data-id="${line.id}" data-index="${i}" aria-label="${t}，${info.roman}"><strong lang="ja">${t}</strong><small>${esc(info.roman)}</small></button>`;}).join('')}</div><div id="mora-explanation" class="mora-explanation" role="status" aria-live="polite">${I('info')}<span>${line.note}</span></div><div class="dialogue-notes"><div><span>本句小知识</span><strong>${line.topic}</strong><p>${line.note}</p></div><div><span>什么时候说</span><strong>把语气也一起学会</strong><p>${line.usage}</p></div></div></section>`;}
  function practicePanel(){const n=pool().length;return `<section class="panel dialogue-practice"><div><div class="eyebrow">YOUR TURN</div><h2>轮到你接台词了。</h2><p>当前范围 ${n} 句，每轮最多 10 题。答错的台词会收进「待复习」。</p></div><div class="dialogue-practice-actions"><label for="dialogue-mode" class="sr-only">台词小测方式</label><select id="dialogue-mode">${[['meaning','看台词选意思'],['blank','补全缺失假名'],['listening','听台词选意思']].map(([id,label])=>`<option value="${id}" ${ui.mode===id?'selected':''}>${label}</option>`).join('')}</select><button class="button" data-action="dialogue-start" ${n?'':'disabled'}>来一轮小测 ${I('arrow')}</button></div></section>`;}
  function library(){const list=pool(),p=progress(),s=stats();if(!list.some(l=>l.id===ui.selected)&&list.length)ui.selected=list[0].id;const selected=find(ui.selected);return `${intro()}<div class="dialogue-summary"><span><strong>${D.lines.length}</strong> 句常用表达</span><span><strong>${s.learned}</strong> 句已标熟悉</span><span><strong>${s.review}</strong> 句待复习</span><span>台词小测正确率 <strong>${s.attempts?Math.round(s.correct/s.attempts*100)+'%':'—'}</strong></span></div>${controls()}${list.length?`<div class="dialogue-layout"><aside class="dialogue-library panel"><div class="dialogue-library-heading">今日的台词本 <small>${list.length} SCENES</small></div><div class="dialogue-line-list">${list.map(l=>`<button class="dialogue-line ${l.id===ui.selected?'active':''}" aria-pressed="${l.id===ui.selected}" data-action="dialogue-select" data-id="${l.id}"><span lang="ja">${l.text}</span><small>${l.meaning}</small>${p.learned.includes(l.id)?'<span class="line-status" aria-label="已熟悉">✓</span>':p.records[l.id]?.review?'<span class="line-status review-status" aria-label="待复习">↻</span>':''}</button>`).join('')}</div></aside>${lineCard(selected)}</div>`:`<section class="panel empty-state"><div class="big" lang="ja">言</div><h2>${ui.filter==='review'?'这些台词暂时没有错题。':'还没有符合筛选条件的台词。'}</h2><p>先挑一句听一听，或者把筛选切回「全部」。</p><button class="button secondary" data-action="dialogue-all">查看全部台词</button></section>`}${practicePanel()}<p class="dialogue-footnote">${I('info')} 台词采用通用日语表达与原创情境，不对应特定作品片段。朗读使用设备日语合成语音；台词小测单独统计，记录包含在学习备份中。</p>`;}
  function prepare(){const c=quiz.queue[quiz.index];quiz.answered=false;quiz.choice='';quiz.explanation='';if(quiz.mode==='blank'){const tokens=D.tokenize(c.kana);quiz.blank=Math.max(0,tokens.indexOf(c.focus));quiz.answer=tokens[quiz.blank];const candidates=[...new Set(KanaData.entries.filter(e=>e.group==='basic').map(e=>e.hira))].filter(t=>t!==quiz.answer);quiz.options=L.shuffle([quiz.answer,...L.shuffle(candidates).slice(0,3)]);}else{quiz.answer=c.meaning;quiz.options=L.shuffle([quiz.answer,...L.shuffle(D.lines.filter(l=>l.meaning!==c.meaning)).slice(0,3).map(l=>l.meaning)]);}}
  function start(custom){if(ui.mode==='listening'&&!hasJapaneseVoice()){toast('听台词练习需要设备提供日语语音，请安装日语语音包后重试。');return;}const selected=custom||pool();if(!selected.length)return;quiz={queue:L.shuffle(selected).slice(0,10),index:0,mode:ui.mode,results:[],done:false};prepare();render();}
  function quizView(){if(quiz.done)return result();const q=quiz,c=q.queue[q.index];return `${intro()}<div class="session-wrap dialogue-quiz"><div class="session-top"><span>${D.groups[c.group].name} · 台词小测</span><span>${q.index+1} / ${q.queue.length}</span><button class="button ghost small" data-action="dialogue-exit">返回台词本 ×</button></div><div class="session-progress"><span style="width:${q.index/q.queue.length*100}%"></span></div><section class="panel question-panel"><div class="question-tag">${q.mode==='blank'?'COMPLETE THE LINE':q.mode==='listening'?'LISTEN TO THE LINE':'WHAT DOES IT MEAN?'}</div><p class="dialogue-quiz-scene">${c.scene}</p>${q.mode==='listening'?`<button class="play-large" data-action="dialogue-speak" data-id="${c.id}" aria-label="播放本题台词">${I('sound')}</button><p class="question-instruction">听一听，选择这句台词的意思。</p>`:q.mode==='blank'?`<div class="cloze-line" lang="ja">${D.tokenize(c.kana).map((t,i)=>i===q.blank?`<span class="blank-token ${q.answered?'filled':''}">${q.answered?q.answer:'？'}</span>`:`<span>${t}</span>`).join('')}</div><p class="question-instruction">${c.meaning} · 补上缺失的假名</p>`:`<div class="dialogue-quiz-text" lang="ja">${c.text}</div><p class="question-instruction">选择这句台词的意思。</p>`}<div class="answer-options">${q.options.map((o,i)=>`<button class="answer-option dialogue-answer ${q.mode==='blank'?'kana-option':''} ${q.answered?o===q.answer?'correct':o===q.choice?'wrong':'':''}" data-action="dialogue-answer" data-value="${esc(o)}" ${q.answered?'disabled':''}>${o}<small>${i+1}</small></button>`).join('')}</div><div class="feedback ${q.answered?q.results.at(-1).correct?'good':'bad':''}" aria-live="polite" role="status">${q.answered?q.explanation:'仔细想一想，或按 1–4 选择。'}</div>${q.answered?`<div class="dialogue-answer-note"><strong lang="ja">${c.text}</strong><span>${c.kana} · ${c.romaji}</span><p>${c.note}</p></div><div class="next-row"><button class="button" data-action="dialogue-next">${q.index===q.queue.length-1?'查看结果':'下一句'} ${I('arrow')}</button><button class="button ghost" data-action="dialogue-speak" data-id="${c.id}">${I('sound')}再听一遍</button></div>`:''}</section></div>`;}
  function result(){const correct=quiz.results.filter(r=>r.correct).length,wrong=quiz.results.filter(r=>!r.correct);return `${intro()}<div class="session-wrap"><section class="panel question-panel"><div class="eyebrow">A NEW LINE, A LITTLE CONFIDENCE</div><h2>这段小故事，你听懂了多少？</h2><div class="result-figure">${Math.round(correct/quiz.queue.length*100)}<small>%</small></div><p class="muted">${correct} / ${quiz.queue.length} 题答对 · 台词小测单独统计</p><div class="button-row" style="justify-content:center">${wrong.length?'<button class="button" data-action="dialogue-retry">重练本轮错题</button>':''}<button class="button secondary" data-action="dialogue-exit">回到台词本</button></div>${wrong.length?`<div class="result-list"><div class="muted">这几句，值得再听一次</div>${wrong.map(r=>`<div class="dialogue-result-row"><strong lang="ja">${r.line.text}</strong><span>${r.line.meaning}</span><button class="sound-button" data-action="dialogue-speak" data-id="${r.line.id}" aria-label="播放 ${r.line.text}">${I('sound')}</button></div>`).join('')}</div>`:'<p class="muted" style="margin-top:25px">全对啦。试试换个场景，或者补全假名。</p>'}</section></div>`;}
  function answer(value){if(!quiz||quiz.done||quiz.answered||!quiz.options.includes(value))return;const c=quiz.queue[quiz.index],correct=value===quiz.answer;quiz.answered=true;quiz.choice=value;quiz.results.push({line:c,correct});quiz.explanation=correct?'答对了，这句台词接住啦！':`再记一遍：${quiz.answer}。已加入台词「待复习」。`;const p=progress(),r=p.records[c.id]||{attempts:0,correct:0,review:false};r.attempts++;if(correct)r.correct++;r.review=!correct;p.records[c.id]=r;const state=getState(),day=L.dateKey();state.daily[day]=(state.daily[day]||0)+1;save();render();}
  function handle(action,b){
   if(!action.startsWith('dialogue-'))return false;
   if(action==='dialogue-select'){ui.selected=b.dataset.id;render();}
   else if(action==='dialogue-group'){ui.group=b.dataset.group;render();}
   else if(action==='dialogue-all'){ui.group='all';ui.filter='all';render();}
   else if(action==='dialogue-speak'){const c=find(b.dataset.id);if(c)speak(c.kana);}
   else if(action==='dialogue-token'){const c=find(b.dataset.id),index=Number(b.dataset.index);if(c){const token=D.tokenize(c.kana)[index],info=tokenInfo(c,token,index);const box=document.querySelector('#mora-explanation');if(box)box.innerHTML=I('info')+`<span>${info.detail}</span>`;document.querySelectorAll('.mora').forEach(el=>el.classList.toggle('playing',el===b));if(token!=='っ')speak(D.spokenToken(c,index));}}
   else if(action==='dialogue-mark'){const id=b.dataset.id,p=progress();if(find(id)){p.learned=p.learned.includes(id)?p.learned.filter(k=>k!==id):[...p.learned,id];save();render();}}
   else if(action==='dialogue-start')start();
   else if(action==='dialogue-answer')answer(b.dataset.value);
   else if(action==='dialogue-next'&&quiz?.answered){quiz.index++;if(quiz.index>=quiz.queue.length)quiz.done=true;else prepare();render();}
   else if(action==='dialogue-exit'){quiz=null;if('speechSynthesis' in window)speechSynthesis.cancel();render();}
   else if(action==='dialogue-retry'){const wrong=quiz?.results.filter(r=>!r.correct).map(r=>r.line)||[];if(wrong.length)start(wrong);}
   return true;
  }
  function change(el){if(el.id==='dialogue-filter'){ui.filter=el.value;render();}else if(el.id==='dialogue-mode')ui.mode=el.value;else if(el.id==='dialogue-reading'){ui.showReading=el.checked;render();}else return false;return true;}
  function keydown(event){if(!quiz||quiz.done||/^(INPUT|SELECT|TEXTAREA)$/.test(event.target.tagName)||event.ctrlKey||event.altKey||event.metaKey)return;if(/^[1-4]$/.test(event.key)&&!quiz.answered){event.preventDefault();answer(quiz.options[Number(event.key)-1]);}else if(event.key==='Enter'&&quiz.answered){event.preventDefault();handle('dialogue-next',{});}}
  return {render:()=>quiz?quizView():library(),handle,change,keydown,leave:()=>{quiz=null;},stats};
 }
 root.KanaDialogue={create};
})(typeof globalThis!=='undefined'?globalThis:this);
